static inline int ailuni_category_index(uint32_t cp) {
    int lo = 0, hi = (int)(sizeof ailuni_catranges / sizeof ailuni_catranges[0]) - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (cp < ailuni_catranges[mid].lo) hi = mid - 1;
        else if (cp > ailuni_catranges[mid].hi) lo = mid + 1;
        else return ailuni_catranges[mid].cat;
    }
    return 0;
}

static const char *ailuni_category(uint32_t cp) {
    return ailuni_categories[ailuni_category_index(cp)];
}

static inline int ailuni_name_entry_of(uint32_t cp, const ailuni_name_entry **found) {
    int lo = 0, hi = (int)(sizeof ailuni_names / sizeof ailuni_names[0]) - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (cp < ailuni_names[mid].cp) hi = mid - 1;
        else if (cp > ailuni_names[mid].cp) lo = mid + 1;
        else { *found = &ailuni_names[mid]; return 1; }
    }
    return 0;
}

static inline int ailuni_hex_name(char *buf, size_t size, const char *prefix, uint32_t cp) {
    int n = snprintf(buf, size, "%s-%04X", prefix, (unsigned)cp);
    return n > 0 && (size_t)n < size;
}

static const char *const ailuni_l_jamo[19] = {
    "G", "GG", "N", "D", "DD", "R", "M", "B", "BB", "S", "SS", "", "J", "JJ", "C", "K", "T", "P", "H"
};
static const char *const ailuni_v_jamo[21] = {
    "A", "AE", "YA", "YAE", "EO", "E", "YEO", "YE", "O", "WA", "WAE", "OE", "YO", "U", "WEO", "WE", "WI",
    "YU", "EU", "YI", "I"
};
static const char *const ailuni_t_jamo[28] = {
    "", "G", "GG", "GS", "N", "NJ", "NH", "D", "L", "LG", "LM", "LB", "LS", "LT", "LP", "LH", "M", "B",
    "BS", "S", "SS", "NG", "J", "C", "K", "T", "P", "H"
};

/* The name of `cp` in `buf` (at least 128 bytes); 1 when it has one, 0 for "no such name". */
static inline int ailuni_name(uint32_t cp, char *buf, size_t size) {
    const ailuni_name_entry *entry;
    if (ailuni_name_entry_of(cp, &entry)) {
        if ((size_t)entry->len >= size) return 0;
        memcpy(buf, ailuni_name_pool + entry->off, entry->len);
        buf[entry->len] = '\0';
        return 1;
    }
    if (AILUNI_S_BASE <= cp && cp < AILUNI_S_BASE + AILUNI_S_COUNT) {
        uint32_t index = cp - AILUNI_S_BASE;
        int n = snprintf(buf, size, "HANGUL SYLLABLE %s%s%s", ailuni_l_jamo[index / AILUNI_N_COUNT],
                         ailuni_v_jamo[(index % AILUNI_N_COUNT) / AILUNI_T_COUNT], ailuni_t_jamo[index % AILUNI_T_COUNT]);
        return n > 0 && (size_t)n < size;
    }
    for (size_t i = 0; i < sizeof ailuni_name_ranges / sizeof ailuni_name_ranges[0]; i++)
        if (ailuni_name_ranges[i].lo <= cp && cp <= ailuni_name_ranges[i].hi)
            return ailuni_hex_name(buf, size, ailuni_name_ranges[i].prefix, cp);
    return 0;
}

static inline const ailuni_decomp_entry *ailuni_decomp_of(uint32_t cp) {
    int lo = 0, hi = (int)(sizeof ailuni_decomp / sizeof ailuni_decomp[0]) - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (cp < ailuni_decomp[mid].cp) hi = mid - 1;
        else if (cp > ailuni_decomp[mid].cp) lo = mid + 1;
        else return &ailuni_decomp[mid];
    }
    return NULL;
}

static inline int ailuni_ccc_of(uint32_t cp) {
    int lo = 0, hi = (int)(sizeof ailuni_ccc / sizeof ailuni_ccc[0]) - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (cp < ailuni_ccc[mid].cp) hi = mid - 1;
        else if (cp > ailuni_ccc[mid].cp) lo = mid + 1;
        else return ailuni_ccc[mid].ccc;
    }
    return 0;
}

static inline int ailuni_compose_pair(uint32_t a, uint32_t b, uint32_t *out) {
    if (AILUNI_L_BASE <= a && a < AILUNI_L_BASE + AILUNI_L_COUNT && AILUNI_V_BASE <= b && b < AILUNI_V_BASE + AILUNI_V_COUNT) {
        *out = AILUNI_S_BASE + ((a - AILUNI_L_BASE) * AILUNI_V_COUNT + (b - AILUNI_V_BASE)) * AILUNI_T_COUNT;
        return 1;
    }
    if (AILUNI_S_BASE <= a && a < AILUNI_S_BASE + AILUNI_S_COUNT && (a - AILUNI_S_BASE) % AILUNI_T_COUNT == 0
            && AILUNI_T_BASE < b && b < AILUNI_T_BASE + AILUNI_T_COUNT) {
        *out = a + (b - AILUNI_T_BASE);
        return 1;
    }
    int lo = 0, hi = (int)(sizeof ailuni_comp / sizeof ailuni_comp[0]) - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        const ailuni_comp_entry *e = &ailuni_comp[mid];
        if (a < e->a || (a == e->a && b < e->b)) hi = mid - 1;
        else if (a > e->a || (a == e->a && b > e->b)) lo = mid + 1;
        else { *out = e->c; return 1; }
    }
    return 0;
}

/* Append the full decomposition of `cp` to out[*n], growing it with realloc. `compat` selects NFKD. */
static int ailuni_decompose_one(uint32_t cp, int compat, uint32_t **out, int64_t *n, int64_t *cap) {
    if (AILUNI_S_BASE <= cp && cp < AILUNI_S_BASE + AILUNI_S_COUNT) {
        uint32_t index = cp - AILUNI_S_BASE;
        uint32_t parts[3] = {AILUNI_L_BASE + index / AILUNI_N_COUNT, AILUNI_V_BASE + (index % AILUNI_N_COUNT) / AILUNI_T_COUNT,
                             AILUNI_T_BASE + index % AILUNI_T_COUNT};
        int count = parts[2] == AILUNI_T_BASE ? 2 : 3;
        for (int i = 0; i < count; i++) {
            if (*n + 1 > *cap) {
                int64_t next = *cap ? *cap * 2 : 16;
                uint32_t *grown = (uint32_t *)realloc(*out, (size_t)next * sizeof(uint32_t));
                if (!grown) return 0;
                *out = grown; *cap = next;
            }
            (*out)[(*n)++] = parts[i];
        }
        return 1;
    }
    const ailuni_decomp_entry *entry = ailuni_decomp_of(cp);
    if (!entry || (entry->compat && !compat)) {
        if (*n + 1 > *cap) {
            int64_t next = *cap ? *cap * 2 : 16;
            uint32_t *grown = (uint32_t *)realloc(*out, (size_t)next * sizeof(uint32_t));
            if (!grown) return 0;
            *out = grown; *cap = next;
        }
        (*out)[(*n)++] = cp;
        return 1;
    }
    for (int i = 0; i < entry->len; i++)
        if (!ailuni_decompose_one(ailuni_decomp_pool[entry->off + i], compat, out, n, cap)) return 0;
    return 1;
}

/* Normalize `in` with form 0 NFC, 1 NFD, 2 NFKC, 3 NFKD. Returns a malloc'd array in *out. */
static int ailuni_normalize(int form, const uint32_t *in, int64_t n, uint32_t **out, int64_t *outn) {
    uint32_t *work = NULL;
    int64_t used = 0, cap = 0;
    int compat = form >= 2;
    for (int64_t i = 0; i < n; i++)
        if (!ailuni_decompose_one(in[i], compat, &work, &used, &cap)) { free(work); return 0; }
    /* canonical ordering: a stable insertion sort inside each run of non-starters */
    for (int64_t i = 1; i < used; i++) {
        uint32_t ch = work[i];
        int c = ailuni_ccc_of(ch);
        if (c == 0) continue;
        int64_t j = i;
        while (j > 0) {
            int prev = ailuni_ccc_of(work[j - 1]);
            if (prev == 0 || prev <= c) break;
            work[j] = work[j - 1];
            j--;
        }
        work[j] = ch;
    }
    if (form == 0 || form == 2) {
        if (used == 0) { *out = work; *outn = 0; return 1; }
        int64_t comp_pos = 1, starter_pos = 0;
        uint32_t starter = work[0];
        int last_class = -1;
        for (int64_t src = 1; src < used; src++) {
            uint32_t ch = work[src];
            int ch_class = ailuni_ccc_of(ch);
            uint32_t composite;
            if ((last_class < ch_class || last_class == 0) && ailuni_compose_pair(starter, ch, &composite)) {
                work[starter_pos] = composite;
                starter = composite;
                continue;
            }
            if (ch_class == 0) {
                starter = ch;
                starter_pos = comp_pos;
            }
            last_class = ch_class;
            work[comp_pos++] = ch;
        }
        used = comp_pos;
    }
    *out = work;
    *outn = used;
    return 1;
}

